-- Conteúdo v3: textos reescritos em linguagem clara, revisados por 3 professores; 18 lições
select public.substituir_conteudo($conteudo${"temas":[{"id":"luzes","icone":"💡","licoes":["luzes-quem-vem-la","luzes-quem-mais","luzes-trabalhando"],"titulo":"Luzes de navegação"},{"id":"sons","icone":"📯","licoes":["apitos-manobra","sons-cerracao-canais","sons-canais"],"titulo":"Sinais sonoros"},{"id":"balizamento","icone":"🛟","licoes":["balizamento-entrando","balizamento-cardinais","balizamento-outras-marcas"],"titulo":"Balizamento IALA B"},{"id":"governo","icone":"🧭","licoes":["governo-quem-da-passagem","governo-risco-veleiros"],"titulo":"Regras de governo"},{"id":"marinharia","icone":"🪢","licoes":["nos-arremate-emendas","nos-alcas-voltas","nos-na-pratica"],"titulo":"Marinharia: nós e voltas"},{"id":"salvatagem","icone":"🦺","licoes":["salvatagem-seguranca","salvatagem-homem-ao-mar","salvatagem-socorro","salvatagem-prevencao"],"titulo":"Salvatagem e sobrevivência"}],"licoes":[{"id":"luzes-quem-vem-la","temaId":"luzes","titulo":"Quem vem lá?","descricao":"Bombordo, boreste e as luzes que mostram quem vem e para onde aponta","cartoes":[{"id":"c-bordos","cena":{"tipo":"bordos"},"tipo":"conceito","texto":"Para falar dos lados de um barco, a náutica usa dois nomes. Olhando para a proa (a frente do barco), o lado esquerdo se chama bombordo e o direito se chama boreste. À noite, cada lado tem uma luz de cor própria, as luzes de bordo: vermelha em bombordo e verde em boreste.","titulo":"Bombordo e boreste","falaMarujo":"Bombordo e vermelho terminam em o; boreste e verde, em e."},{"id":"c-setores","cena":{"tipo":"luzes-noite","aspecto":0,"embarcacao":{"tipo":"propulsao-mecanica"}},"pose":"assustado","tipo":"conceito","texto":"À noite você não enxerga o barco, só as luzes dele. A maioria dessas luzes brilha apenas para um lado, que é o setor dela. Por isso, as luzes que você vê contam para onde o barco aponta.\n\nO barco a motor tem uma luz branca no alto, a luz de mastro, que brilha para a frente.","titulo":"Cada luz tem seu setor","falaMarujo":"Branca alta à vista? Barco a motor, e você está do lado da proa dele."},{"id":"c-luz-alcancado","tipo":"conceito","titulo":"A luz de alcançado","texto":"Na popa (a parte de trás do barco) fica a luz de alcançado, que também é branca. Ela só aparece para quem está atrás do barco. Ou seja, se você só vê essa luz branca, está olhando a popa dele.","falaMarujo":"Só uma branca baixinha? Você está vendo a popa."},{"id":"c-luzes-trocadas","tipo":"conceito","titulo":"De frente, as cores se invertem","texto":"Cada luz de bordo só aparece do seu lado: a vermelha por bombordo e a verde por boreste. Quando um barco vem de frente para você, os lados dele ficam espelhados. Assim, a verde dele aparece à sua esquerda e a vermelha à sua direita.","falaMarujo":"Barco de frente é espelho: as cores trocam de lado."},{"id":"c-luzes-roda-a-roda","tipo":"conceito","titulo":"Roda a roda","texto":"Se você vê a luz de mastro junto com a vermelha e a verde, é uma embarcação a motor vindo bem de frente para você. Essa situação se chama roda a roda (proa contra proa). Nela, você e a outra embarcação guinam (viram) para boreste e passam bombordo com bombordo.","falaMarujo":"Vermelha e verde juntas? Ela vem na sua direção!"},{"id":"c-quem-e-quem","cena":{"tipo":"luzes-noite","aspecto":0,"embarcacao":{"tipo":"vela"}},"pose":"ensinando","tipo":"conceito","texto":"Um veleiro navegando à vela não tem luz de mastro. Ele mostra só as luzes de bordo e a de alcançado. Por isso, vermelha e verde sem a branca alta indicam um veleiro, e você, de lancha a motor, deve se afastar dele.\n\nSe o veleiro estiver usando o motor, acende a luz de mastro e passa a contar como embarcação a motor.","titulo":"Veleiro não tem luz de mastro","falaMarujo":"Sem a branca alta em cima das cores? É veleiro!"},{"id":"c-fundeada-luz","tipo":"conceito","titulo":"Barco fundeado","texto":"Embarcação fundeada é a que está parada, presa pela âncora. Se ela tem menos de 50 m, mostra uma única luz branca circular, ou seja, visível de todos os lados. Ela não acende as luzes de bordo, porque não está navegando.","falaMarujo":"Uma branca sozinha, parada no lugar? Barco na âncora."},{"id":"q-proa-motor","cena":{"tipo":"luzes-noite","aspecto":0,"embarcacao":{"tipo":"propulsao-mecanica"}},"tipo":"multipla-escolha","opcoes":["Embarcação a motor em roda a roda: as duas guinam para boreste","Veleiro vindo de frente: você deve manter o seu rumo","Embarcação a motor se afastando: siga sem mudar nada","Embarcação fundeada: contorne por qualquer um dos lados"],"correta":0,"enunciado":"À noite, você vê bem à sua proa uma luz branca alta, uma vermelha e uma verde, e elas estão se aproximando. Que barco é esse e o que você deve fazer?","explicacao":"A branca alta é a luz de mastro, e ver a vermelha e a verde ao mesmo tempo mostra que o barco aponta para você. Então é uma embarcação a motor vindo de frente, em roda a roda. Nesse caso, as duas guinam para boreste e passam bombordo com bombordo. Um veleiro não teria a branca alta.","referencia":"RIPEAM · Regras 14 e 23"},{"id":"q-popa-motor","cena":{"tipo":"luzes-noite","aspecto":180,"embarcacao":{"tipo":"propulsao-mecanica"}},"tipo":"multipla-escolha","opcoes":["A luz de alcançado: você está vendo a popa dele","A luz de mastro: ele vem de frente para você","Uma luz de fundeado: ele está parado na âncora","Uma luz de bordo: você está ao lado dele"],"correta":0,"enunciado":"À noite, já bem perto, você vê um barco em movimento que mostra só uma luz branca baixa, sem vermelha nem verde. Que luz é essa?","explicacao":"A luz de alcançado é branca e só aparece para quem está atrás do barco, num setor de 135° na popa. Se você vê só ela e está chegando mais perto, você está ultrapassando, e cabe a você se manter afastado. Se ele viesse de frente, você veria também a vermelha e a verde.","referencia":"RIPEAM · Regras 13 e 21(c)"},{"id":"q-traves-be","cena":{"tipo":"luzes-noite","aspecto":70,"embarcacao":{"tipo":"propulsao-mecanica"}},"tipo":"multipla-escolha","opcoes":["Do lado de boreste dele","Do lado de bombordo dele","Atrás dele, pela popa","Bem na frente da proa dele"],"correta":0,"enunciado":"À noite, você vê num barco uma luz branca alta e uma luz verde, sem a vermelha. De que lado dele você está?","explicacao":"A luz verde fica no boreste do barco e só aparece desse lado, da proa até 22,5° para trás do través (a linha que cruza o meio do barco de lado a lado). Por isso, se você vê a verde sem a vermelha, está pelo boreste dele. Se estivesse atrás, veria só a luz de alcançado, e se estivesse bem na proa, veria a vermelha e a verde juntas.","referencia":"RIPEAM · Regras 15, 17(a)(ii), 17(c) e 21(b)"},{"id":"q-vela-proa","cena":{"tipo":"luzes-noite","aspecto":0,"embarcacao":{"tipo":"vela"}},"tipo":"multipla-escolha","opcoes":["Uma embarcação a vela, vindo de proa","Uma embarcação a motor, vindo de proa","Uma embarcação fundeada, parada na âncora","Um pesqueiro de arrasto, vindo de proa"],"correta":0,"enunciado":"À noite, um barco vem na sua direção mostrando a vermelha e a verde juntas, mas sem nenhuma luz branca acima delas. Que barco é?","explicacao":"Um veleiro navegando à vela mostra as luzes de bordo e a de alcançado, mas não tem luz de mastro. Por isso, sem a branca alta, é veleiro. Em geral, a embarcação a motor é que deve se manter afastada dele.","referencia":"RIPEAM · Regras 18 e 25"},{"id":"q-fundeada","cena":{"tipo":"luzes-noite","aspecto":40,"embarcacao":{"tipo":"fundeada"}},"tipo":"multipla-escolha","opcoes":["Embarcação fundeada (menor que 50 m)","Embarcação a motor vindo de frente","Embarcação sem governo, à deriva","Veleiro navegando à vela"],"correta":0,"enunciado":"À noite, você vê uma única luz branca, visível de todos os lados, que fica sempre no mesmo lugar. O que ela provavelmente indica?","explicacao":"Uma embarcação fundeada com menos de 50 m mostra uma luz branca circular, no lugar onde ela possa ser mais bem vista. Ela não acende as luzes de bordo porque não está navegando. Cuidado: uma embarcação a motor com menos de 7 m e até 7 nós pode mostrar só uma branca circular (e, se possível, as de bordo), mas ela estaria se movendo.","referencia":"RIPEAM · Regras 23(d) e 30"}]},{"id":"luzes-quem-mais","temaId":"luzes","titulo":"Quem mais vem lá?","descricao":"Luzes de navio grande, sem governo, pesca de arrasto e fundeado grande","cartoes":[{"id":"c-dois-mastros","cena":{"tipo":"luzes-noite","aspecto":0,"embarcacao":{"tipo":"propulsao-mecanica","porte":"maior50"}},"tipo":"conceito","texto":"As luzes também contam o tamanho de quem vem. Uma embarcação de propulsão mecânica (o nome oficial do barco a motor) com 50 m ou mais mostra duas luzes de mastro brancas, e a de ré (de trás) fica mais alta que a de vante (da frente). Barcos menores podem acender a segunda, mas a partir de 50 m ela é obrigatória.","titulo":"Navio grande tem dois mastros","falaMarujo":"Duas brancas em escada? É navio grandão. Dá espaço!"},{"id":"c-navio-de-frente","tipo":"conceito","titulo":"Navio grande vindo de frente","texto":"Quando esse navio vem na sua direção, você vê as duas luzes de mastro, a de trás mais alta, e ainda a vermelha e a verde. Esse conjunto avisa que um navio grande está vindo bem para cima da sua lancha.","falaMarujo":"Duas brancas e as duas cores? Navio grande vindo aí!"},{"id":"c-sem-governo","cena":{"tipo":"luzes-noite","aspecto":60,"embarcacao":{"tipo":"sem-governo","comSeguimento":false}},"tipo":"conceito","texto":"Às vezes um navio perde o controle por pane na máquina ou no leme. Ele fica sem governo, ou seja, não consegue manobrar. À noite, avisa isso com duas luzes vermelhas circulares, uma sobre a outra. Como ele não consegue desviar, quem desvia é você.\n\nSe ainda tem seguimento (se ainda anda pela água), mostra também as luzes de bordo e a de alcançado.","titulo":"Vermelha sobre vermelha","falaMarujo":"Vermelha sobre vermelha: o navio não governa. Quem se afasta é você."},{"id":"c-arrasto","cena":{"tipo":"luzes-noite","aspecto":30,"embarcacao":{"tipo":"pesca-arrasto"}},"tipo":"conceito","texto":"Barcos pescando não manobram com facilidade, por isso sua lancha deve sair do caminho deles. O pesqueiro de arrasto, que puxa a rede atrás dele, mostra duas luzes circulares: verde em cima e branca embaixo. Como a rede vai por trás, nunca passe perto da popa dele.","titulo":"Verde sobre branca: arrasto","falaMarujo":"Verde sobre branca: tem rede arrastando aí atrás!"},{"id":"c-arrasto-extras","tipo":"conceito","titulo":"Outras luzes do arrasto","texto":"Se o pesqueiro de arrasto tiver 50 m ou mais, mostra também uma luz de mastro a ré, mais alta que a verde. E, quando tem seguimento, acende as luzes de bordo e a de alcançado, como qualquer barco que está andando.","falaMarujo":"Pesqueiro andando também mostra as cores de bordo."},{"id":"c-fundeado-grande","cena":{"tipo":"luzes-noite","aspecto":270,"embarcacao":{"tipo":"fundeada","porte":"maior50"}},"tipo":"conceito","texto":"Um navio grande parado na âncora também avisa o seu tamanho. Fundeado com 50 m ou mais, ele mostra duas luzes brancas circulares, e a de vante fica mais alta que a de ré. É o contrário do navio navegando, em que a luz de mastro de ré é a mais alta.","titulo":"Fundeado grande","falaMarujo":"Fundeado, a alta vai na proa. Navegando, a alta vai na popa."},{"id":"q-dois-mastros","cena":{"tipo":"luzes-noite","aspecto":0,"embarcacao":{"tipo":"propulsao-mecanica","porte":"maior50"}},"tipo":"multipla-escolha","opcoes":["Navio a motor com 50 m ou mais, vindo de frente","Duas lanchas pequenas lado a lado, vindo de frente","Navio com 50 m ou mais, parado na âncora","Veleiro com o motor desligado, vindo de frente"],"correta":0,"enunciado":"À noite, bem à sua proa, você vê duas luzes brancas (a de trás mais alta), uma vermelha e uma verde. Que barco vem lá?","explicacao":"Duas luzes de mastro, com a de ré mais alta, são de embarcação a motor com 50 m ou mais. Como você vê a vermelha e a verde juntas, ele vem bem na sua direção.","referencia":"RIPEAM · Regra 23(a)"},{"id":"q-sem-governo","cena":{"tipo":"luzes-noite","aspecto":120,"embarcacao":{"tipo":"sem-governo","comSeguimento":false}},"tipo":"multipla-escolha","opcoes":["Embarcação sem governo, sem seguimento","Embarcação parada, fundeada na âncora","Pesqueiro de arrasto trabalhando","Navio dando máquinas atrás"],"correta":0,"enunciado":"À noite, você vê só duas luzes vermelhas, uma em cima da outra, visíveis de qualquer lado. Que barco é esse?","explicacao":"Duas vermelhas circulares, uma sobre a outra, indicam embarcação sem governo. Como não aparecem as luzes de bordo nem a de alcançado, ela está parada na água, sem seguimento. Ela não consegue sair do seu caminho, então quem manobra é você.","referencia":"RIPEAM · Regras 18 e 27(a)"},{"id":"q-arrasto","cena":{"tipo":"luzes-noite","aspecto":0,"embarcacao":{"tipo":"pesca-arrasto"}},"tipo":"multipla-escolha","opcoes":["Pesqueiro de arrasto, com seguimento, vindo na sua direção","Embarcação sem governo, com seguimento, vindo na sua direção","Veleiro que também está usando o motor","Embarcação fundeada com a popa voltada para você"],"correta":0,"enunciado":"À noite, bem à sua proa, você vê duas luzes circulares, verde em cima e branca embaixo, e ainda as luzes de bordo vermelha e verde. Que barco é?","explicacao":"Verde sobre branca indica pesca de arrasto. As luzes de bordo mostram que ele tem seguimento, e ver as duas ao mesmo tempo mostra que ele vem de frente para você.","referencia":"RIPEAM · Regra 26(b)"},{"id":"q-fundeado-grande","cena":{"tipo":"luzes-noite","aspecto":90,"embarcacao":{"tipo":"fundeada","porte":"maior50"}},"tipo":"multipla-escolha","opcoes":["Navio fundeado com 50 m ou mais","Navio a motor com 50 m ou mais, navegando","Duas lanchas fundeadas, uma perto da outra","Pesqueiro parado recolhendo a rede"],"correta":0,"enunciado":"À noite, você vê duas luzes brancas paradas, visíveis de todos os lados, e a da frente (vante) é mais alta que a de trás (ré). O que é?","explicacao":"Um navio fundeado com 50 m ou mais mostra duas brancas circulares, com a de vante mais alta. No navio navegando é o contrário: a luz de mastro de ré é a mais alta.","referencia":"RIPEAM · Regra 30(a)"},{"id":"q-preferencia-pesca","cena":{"tipo":"luzes-noite","aspecto":330,"embarcacao":{"tipo":"pesca-arrasto"}},"tipo":"multipla-escolha","opcoes":["Você, que está na lancha","O pesqueiro, porque também é a motor","Quem estiver mais à direita","Ninguém, os dois mantêm o rumo"],"correta":0,"enunciado":"Em mar aberto, você está de lancha e vê à proa um barco com uma luz verde sobre uma branca. Quem deve se manter fora do caminho do outro?","explicacao":"Verde sobre branca é pesca de arrasto, e a embarcação a motor deve se manter fora do caminho de quem está pescando. O mesmo vale diante de uma embarcação sem governo ou de um veleiro. Dê bastante espaço, principalmente pela popa, onde vai a rede.","referencia":"RIPEAM · Regra 18(a)"}]},{"id":"luzes-trabalhando","temaId":"luzes","titulo":"Luzes de quem está trabalhando","descricao":"Luzes de quem pesca, faz serviço no mar, tem calado restrito ou reboca","cartoes":[{"id":"c-luzes-trabalho","pose":"ensinando","tipo":"conceito","texto":"Algumas embarcações estão trabalhando e não conseguem desviar de você. À noite, elas avisam isso com luzes extras, uma sobre a outra. O barco que pesca sem ser de arrasto, com rede de espera ou espinhel (linha comprida cheia de anzóis), mostra duas luzes circulares: vermelha em cima e branca embaixo.","titulo":"Quem trabalha avisa no mastro","falaMarujo":"Verde sobre branca é arrasto. Vermelha sobre branca, outra pesca."},{"id":"c-pesca-aparelho-longo","tipo":"conceito","titulo":"Rede comprida ganha mais uma luz","texto":"Às vezes a rede ou o espinhel se estende por mais de 150 m a partir do barco. Nesse caso, o pescador acende mais uma luz branca circular, do lado em que está o aparelho de pesca. Assim, você sabe para que lado a rede está.","falaMarujo":"Branca de lado mostra onde está a rede."},{"id":"q-pesca-comum","tipo":"multipla-escolha","opcoes":["Pescando, mas não de arrasto","Pescando de arrasto","Sem governo, sem manobrar","Levando prático em serviço"],"correta":0,"enunciado":"À noite, você vê num barco duas luzes circulares, uma sobre a outra: vermelha em cima e branca embaixo. O que esse barco está fazendo?","explicacao":"Vermelha sobre branca indica embarcação pescando, menos de arrasto. O arrasto mostra verde sobre branca, e a embarcação sem governo mostra duas vermelhas. Já o barco de prático em serviço (o profissional que guia navios na entrada dos portos) mostra o inverso: branca sobre vermelha.","referencia":"RIPEAM · Regras 26(c) e 29"},{"id":"c-manobra-restrita","tipo":"conceito","titulo":"Vermelha, branca, vermelha","texto":"Uma embarcação com manobra restrita está fazendo um serviço que a impede de desviar, como dragar o fundo ou lançar um cabo submarino. Para avisar, ela mostra três luzes circulares em linha vertical: vermelha em cima, branca no meio e vermelha embaixo.","falaMarujo":"Vermelha, branca, vermelha: está trabalhando, não desvia."},{"id":"c-trabalho-seguimento","tipo":"conceito","titulo":"Trabalhando e andando","texto":"Quando estão com seguimento, ou seja, andando pela água, o pesqueiro e a embarcação com manobra restrita mostram também as luzes de bordo e a de alcançado. A embarcação com manobra restrita acende ainda a luz de mastro.","falaMarujo":"Andando? Então as cores de bordo também acendem."},{"id":"q-manobra-restrita","tipo":"multipla-escolha","opcoes":["Embarcação com capacidade de manobra restrita","Embarcação restrita pelo seu calado","Embarcação sem governo, à deriva","Pesqueiro de arrasto com a rede na água"],"correta":0,"enunciado":"À noite, você vê três luzes circulares em linha vertical: vermelha em cima, branca no meio e vermelha embaixo. O que elas indicam?","explicacao":"Vermelha, branca e vermelha indicam manobra restrita, como em dragagem, serviço submarino ou reabastecimento no mar. Como ela não consegue sair do seu caminho, dê espaço.","referencia":"RIPEAM · Regras 18 e 27(b)"},{"id":"c-calado-restrito","tipo":"conceito","titulo":"Três vermelhas: calado restrito","texto":"Calado é a profundidade que o casco alcança na água, medida da linha d'água até o ponto mais fundo do casco. Um navio restrito pelo calado vai tão fundo que só consegue navegar no trecho mais profundo do canal, ou seja, não tem para onde desviar. Para avisar, ele pode exibir três luzes vermelhas circulares em linha vertical, além das luzes normais. Quando vir esse sinal, não atrapalhe a passagem dele.","falaMarujo":"Três vermelhas: navio fundo, deixa o canal livre."},{"id":"q-calado-restrito","tipo":"multipla-escolha","opcoes":["Restrito pelo seu calado: só pode navegar ali","Sem governo: não consegue manobrar","Rebocando: puxa outra embarcação","Fundeado: está parado na âncora"],"correta":0,"enunciado":"Num canal, um navio grande mostra, além das luzes normais, três luzes vermelhas em linha vertical. O que isso quer dizer?","explicacao":"Três vermelhas em linha vertical indicam navio restrito pelo calado. Lancha, veleiro e pesqueiro devem evitar atrapalhar a passagem dele. Sem governo seriam só duas vermelhas.","referencia":"RIPEAM · Regras 18(d) e 28"},{"id":"c-reboque","tipo":"conceito","titulo":"Luz amarela: reboque","texto":"Às vezes um barco a motor está puxando outro, e o cabo entre os dois pode ser comprido. À noite, ele avisa isso com uma luz amarela de reboque, logo acima da luz de alcançado. Além disso, mostra as luzes de bordo e duas luzes de mastro, uma sobre a outra, ou três se o reboque passar de 200 m.","falaMarujo":"Amarela em cima da popa? Tem reboque vindo atrás."},{"id":"q-reboque","tipo":"multipla-escolha","opcoes":["Rebocando outra embarcação","Pescando de arrasto","Parado, fundeado","Pedindo socorro"],"correta":0,"enunciado":"À noite, olhando a popa de um navio, você vê uma luz amarela acima da luz branca de alcançado. O que ele está fazendo?","explicacao":"A luz de reboque é amarela e fica acima da luz de alcançado, por isso ele está rebocando. Cuidado: nunca passe entre o rebocador e o barco rebocado, porque o cabo pode estar quase na superfície.","referencia":"RIPEAM · Regra 24(a)"}]},{"id":"apitos-manobra","temaId":"sons","titulo":"Apitos de manobra","descricao":"O que querem dizer 1, 2 e 3 apitos curtos e o sinal de dúvida","cartoes":[{"id":"c-apitos","cena":{"tipo":"encontro","sinal":"guinando-boreste","manobra":"boreste","vocePara":"boreste"},"pose":"apito","tipo":"conceito","texto":"Os barcos usam o apito para avisar o que vão fazer. O apito curto dura cerca de 1 segundo, e o longo, de 4 a 6 segundos.\n\nQuando duas embarcações a motor se avistam, quem manobra avisa com apitos curtos. Um apito curto quer dizer: estou guinando (virando) para boreste.","titulo":"Curto ou longo?","falaMarujo":"Um curto: vou para boreste."},{"id":"q-1curto","som":"guinando-boreste","cena":{"tipo":"encontro","sinal":"guinando-boreste","manobra":"boreste","vocePara":"boreste"},"tipo":"multipla-escolha","opcoes":["Estou guinando para boreste","Estou guinando para bombordo","Estou dando máquinas atrás","Não entendi suas intenções"],"correta":0,"enunciado":"O navio que vem de frente para você dá este apito. O que ele está dizendo?","explicacao":"Um apito curto quer dizer “estou guinando para boreste”. Em roda a roda, as duas embarcações guinam para boreste e passam bombordo com bombordo. Por isso, a sua lancha também guina para boreste e, ao guinar, dá o seu próprio apito curto. Não é uma resposta: cada embarcação avisa a manobra que ela mesma está fazendo.","referencia":"RIPEAM · Regras 14 e 34(a)"},{"id":"c-apitos-bombordo-atras","tipo":"conceito","titulo":"Dois e três curtos","texto":"Seguindo a mesma lógica, 2 apitos curtos querem dizer que o barco está guinando para bombordo. Já 3 apitos curtos avisam que ele está dando máquinas atrás, ou seja, usando o motor em marcha à ré para frear.","falaMarujo":"Um, dois, três: boreste, bombordo, pra trás!","pose":"apito"},{"id":"q-3curtos","som":"maquinas-atras","cena":{"tipo":"encontro","sinal":"maquinas-atras","manobra":"atras"},"tipo":"multipla-escolha","opcoes":["Estou dando máquinas atrás","Estou guinando para bombordo","Pretendo ultrapassá-lo","Estou fundeado"],"correta":0,"enunciado":"Ouça o apito deste navio. O que ele está fazendo?","explicacao":"Três apitos curtos querem dizer “estou dando máquinas atrás”. Isso não significa que ele já parou: o navio ainda pode ter seguimento, ou seja, continuar andando por um bom tempo.","referencia":"RIPEAM · Regra 34(a)"},{"id":"q-2curtos","som":"guinando-bombordo","cena":{"tipo":"encontro","sinal":"guinando-bombordo","manobra":"bombordo","posicao":"boreste"},"tipo":"multipla-escolha","opcoes":["Estou guinando para bombordo","Estou guinando para boreste","Estou dando máquinas atrás","Não entendi suas intenções"],"correta":0,"enunciado":"Este navio passa pela sua bochecha de boreste (a parte da frente do seu lado direito) e dá este apito. O que ele está dizendo?","explicacao":"Dois apitos curtos querem dizer “estou guinando para bombordo”. Aqui ele já está passando pelo seu boreste, e a guinada só aumenta a distância entre vocês. Cuidado: num roda a roda, guinar para bombordo é errado, porque as duas devem guinar para boreste.","referencia":"RIPEAM · Regras 14 e 34(a)"},{"id":"c-apito-duvida","tipo":"conceito","titulo":"Cinco ou mais: dúvida","texto":"Existe ainda um sinal de alerta: 5 ou mais apitos curtos e rápidos. Ele quer dizer dúvida ou perigo, ou seja, “não entendi o que você vai fazer” ou “sua manobra pode não evitar o perigo”. Esse sinal vale para qualquer embarcação à vista, não só para as a motor.","falaMarujo":"Cinco ou mais apitos curtos: hein?!","pose":"apito"},{"id":"q-duvida","som":"duvida","cena":{"tipo":"encontro","sinal":"duvida","manobra":"nenhuma"},"tipo":"multipla-escolha","opcoes":["Não entendi sua intenção, ou sua manobra pode não evitar o perigo","Estou guinando para boreste e vou passar pelo seu bombordo","Estou dando máquinas atrás e logo vou parar o navio","Estou parado na água, sem nenhum seguimento por enquanto"],"correta":0,"enunciado":"O navio à sua frente dá este sinal. O que ele quer dizer?","explicacao":"Cinco ou mais apitos curtos e rápidos são o sinal de dúvida ou perigo. Ao ouvir isso, reduza a velocidade e faça a sua manobra de forma bem clara e a tempo.","referencia":"RIPEAM · Regras 8 e 34(d)"}]},{"id":"sons-cerracao-canais","temaId":"sons","titulo":"Apitos na neblina","descricao":"O que cada som quer dizer quando ninguém se enxerga","cartoes":[{"id":"c-cerracao","cena":{"tipo":"encontro","sinal":"cerracao-com-seguimento","manobra":"nenhuma"},"pose":"apito","tipo":"conceito","texto":"Na cerração (neblina forte), ninguém se enxerga, então os barcos se avisam pelo som. Com visibilidade restrita, a embarcação que não está fundeada dá o seu sinal em intervalos de no máximo 2 minutos. A embarcação a motor com seguimento, ou seja, andando, dá 1 apito longo.","titulo":"Apito na neblina","falaMarujo":"Neblina e andando? Um longo, no máximo a cada 2 minutos."},{"id":"q-cer-1longo","som":"cerracao-com-seguimento","cena":{"tipo":"encontro","sinal":"cerracao-com-seguimento","manobra":"nenhuma"},"tipo":"multipla-escolha","opcoes":["Embarcação a motor com seguimento","Embarcação a motor parada","Veleiro navegando à vela","Embarcação fundeada"],"correta":0,"enunciado":"Há neblina fechada. A cada 2 minutos, você ouve este apito vindo da cerração. Quem está lá?","explicacao":"Um apito longo, repetido a cada 2 minutos no máximo, indica embarcação a motor com seguimento. Se o som parecer vir de um ponto à frente do seu través (a linha que cruza o meio da lancha de lado a lado), reduza ao mínimo que ainda permita governar e, se preciso, pare.","referencia":"RIPEAM · Regras 19 e 35(a)"},{"id":"c-cerracao-parada","tipo":"conceito","titulo":"Dois longos: parada","texto":"Se a embarcação a motor está parada na água, sem seguimento e sem estar fundeada, ela dá 2 apitos longos na neblina. Ou seja, um longo quer dizer que ela está andando, e dois longos, que está parada.","falaMarujo":"Um longo anda; dois longos, parou.","pose":"apito"},{"id":"q-cer-2longos","som":"cerracao-sem-seguimento","cena":{"tipo":"encontro","sinal":"cerracao-sem-seguimento","manobra":"nenhuma"},"tipo":"multipla-escolha","opcoes":["Embarcação a motor parada, sem seguimento","Embarcação a motor andando, com seguimento","Pedido para ultrapassar pelo seu boreste","Aviso de que está guinando para bombordo"],"correta":0,"enunciado":"Na cerração, agora você ouve este apito, repetido a cada 2 minutos. O que ele significa?","explicacao":"Dois apitos longos indicam embarcação a motor parada, sem seguimento. Ela está ali, mas não está andando.","referencia":"RIPEAM · Regra 35(b)"},{"id":"c-cerracao-restrita","tipo":"conceito","titulo":"Um longo e dois curtos","texto":"Na neblina, quem tem dificuldade para manobrar dá 1 apito longo seguido de 2 curtos. Esse sinal é usado por veleiro, pesqueiro, embarcação sem governo, com manobra restrita, restrita pelo calado, e por quem está rebocando ou empurrando outra embarcação.","falaMarujo":"Longo e dois curtos: esse aí não desvia fácil.","pose":"apito"},{"id":"q-cer-restrita","som":"cerracao-restrita","cena":{"tipo":"encontro","sinal":"cerracao-restrita","manobra":"nenhuma"},"tipo":"multipla-escolha","opcoes":["Veleiro, pesqueiro, sem governo ou com manobra restrita","Lancha a motor andando, com seguimento normal","Embarcação fundeada, presa pela âncora","Navio pedindo para ultrapassar a sua lancha"],"correta":0,"enunciado":"Na neblina, este apito se repete a cada 2 minutos. Quem pode estar apitando?","explicacao":"Um longo seguido de dois curtos é o sinal de quem tem dificuldade para manobrar: veleiro, pesqueiro, embarcação sem governo, com manobra restrita, restrita pelo calado ou rebocando.","referencia":"RIPEAM · Regra 35(c)"},{"id":"c-cerracao-fundeada","tipo":"conceito","titulo":"Fundeado toca o sino","texto":"Embarcação fundeada não apita na neblina. Em vez disso, ela toca o sino rapidamente, por cerca de 5 segundos, em intervalos de no máximo 1 minuto. Assim, se você ouvir um sino na cerração, há um barco parado na âncora por perto.","falaMarujo":"Sino na neblina? Barco fundeado por perto."}]},{"id":"sons-canais","temaId":"sons","titulo":"Canais e curvas","descricao":"Apitos para ultrapassar num canal estreito e antes de uma curva cega","cartoes":[{"id":"c-canal-estreito","cena":{"tipo":"encontro","sinal":"ultrapassar-boreste","manobra":"nenhuma"},"pose":"apito","tipo":"conceito","texto":"Num canal estreito há pouco espaço, por isso a regra é navegar o mais perto do limite do canal que fica pelo seu boreste, como numa estrada, desde que isso seja seguro e praticável.\n\nSe, para ultrapassar, você precisa que o barco da frente manobre, peça antes com o apito. Dois longos e um curto querem dizer: “vou passar pelo seu boreste”.","titulo":"Canal estreito","falaMarujo":"No canal é mão de boreste, que nem estrada!"},{"id":"c-canal-pedidos","tipo":"conceito","titulo":"Pedir por bombordo e concordar","texto":"Para pedir passagem pelo bombordo do barco da frente, o sinal é 2 longos e 2 curtos. Quando quem vai à frente concorda com o pedido, responde com longo, curto, longo, curto.","falaMarujo":"Longo, curto, longo, curto: pode passar!","pose":"apito"},{"id":"q-ultrapassar-be","som":"ultrapassar-boreste","cena":{"tipo":"encontro","sinal":"ultrapassar-boreste","manobra":"nenhuma"},"tipo":"multipla-escolha","opcoes":["Ultrapassar você pelo seu boreste","Ultrapassar você pelo seu bombordo","Avisar que está dando máquinas atrás","Dizer que não entendeu sua manobra"],"correta":0,"enunciado":"Num canal estreito, o navio que vem atrás de você dá este apito. O que ele quer?","explicacao":"Dois longos e um curto querem dizer “pretendo ultrapassá-lo pelo seu boreste”. Se concordar, responda longo, curto, longo, curto e facilite a passagem. Se tiver dúvida, dê pelo menos 5 apitos curtos e rápidos.","referencia":"RIPEAM · Regras 9(e) e 34(c)"},{"id":"q-concordancia","som":"concordancia","cena":{"tipo":"encontro","sinal":"concordancia","manobra":"nenhuma"},"tipo":"multipla-escolha","opcoes":["Concordo com a ultrapassagem","Não concordo, fique atrás","Estou parado, sem seguimento","Estou chegando a uma curva"],"correta":0,"enunciado":"Num canal, você pediu para ultrapassar, e o navio da frente responde com este apito. O que ele disse?","explicacao":"Longo, curto, longo, curto quer dizer “de acordo”. Mesmo com a concordância, quem ultrapassa continua responsável por passar com segurança.","referencia":"RIPEAM · Regras 9(e)(ii) e 34(c)"},{"id":"c-curva-cega","tipo":"conceito","titulo":"Curva cega","texto":"Quando você chega a uma curva cega, em que não dá para ver o outro lado, dê 1 apito longo. Se outra embarcação estiver se aproximando da mesma curva pelo outro lado e ouvir o apito, ela responde também com 1 longo. Assim, as duas sabem que vão se cruzar ali.","falaMarujo":"Curva cega? Um longo antes de entrar.","pose":"apito"},{"id":"q-curva","som":"curva","cena":{"tipo":"encontro","sinal":"curva","manobra":"nenhuma"},"tipo":"multipla-escolha","opcoes":["Tem embarcação chegando à curva: responda com 1 longo","Tem embarcação fundeada na curva: passe devagar","Pedem que você pare: corte as máquinas já","É um pedido de socorro: vá até a curva ajudar"],"correta":0,"enunciado":"Num rio, com boa visibilidade, você se aproxima de uma curva fechada, onde não dá para ver o outro lado. Então, ouve 1 apito longo vindo de trás da curva. O que ele significa?","explicacao":"Um apito longo avisa que um barco está chegando a uma curva ou a um trecho sem visibilidade. Como você também está se aproximando da curva, responda com 1 longo. Depois, passe a curva com atenção e cuidado redobrados, mantendo-se do lado de boreste do canal.","referencia":"RIPEAM · Regras 9(f) e 34(e)"}]},{"id":"balizamento-entrando","temaId":"balizamento","titulo":"Entrando no porto","descricao":"Como as boias laterais mostram o caminho na entrada e na saída do porto","cartoes":[{"id":"c-regiao-b","cena":{"tipo":"canal","sentido":"entrando"},"tipo":"conceito","titulo":"Vermelho a boreste, entrando","texto":"Na entrada de um porto, boias vermelhas e verdes marcam as bordas do canal, o caminho com fundo seguro. O Brasil segue a Região B da IALA, o sistema internacional de boias. Por isso, quando você entra no porto vindo do mar, deixa as vermelhas por boreste (direita) e as verdes por bombordo (esquerda).","falaMarujo":"Voltando pra casa, o vermelho fica à direita!"},{"id":"c-saindo-inverte","tipo":"conceito","titulo":"Saindo, tudo se inverte","texto":"A regra das cores vale para quem entra no porto. Quando você sai para o mar, o lado se inverte: a vermelha fica por bombordo (esquerda) e a verde por boreste (direita). Entrando ou saindo, navegue sempre por dentro do canal balizado, ou seja, entre as duas fileiras de boias.","falaMarujo":"Saindo pro mar, o vermelho passa pra esquerda."},{"id":"c-formatos","cena":{"tipo":"marcas"},"tipo":"conceito","titulo":"Formato e tope também falam","texto":"De longe ou contra o sol, nem sempre dá para ver a cor da boia. Por isso, o formato também indica o lado: a vermelha, de boreste, é cônica, como um cone de ponta para cima, e a verde, de bombordo, é cilíndrica, como uma lata.\n\nO tope (o sinal no alto da boia) repete esse formato. Em boias de outros formatos, como as de pilar ou de charuto, é o tope que diz o lado.","falaMarujo":"Vermelha é cone, verde é lata.","pose":"pensando"},{"id":"q-vermelha-entrando","cena":{"tipo":"canal","oculto":true,"sentido":"entrando"},"tipo":"multipla-escolha","enunciado":"Você está voltando do mar e entrando no porto com a sua lancha. Por qual lado deve deixar as boias vermelhas?","opcoes":["Por boreste, à minha direita","Por bombordo, à minha esquerda","Por qualquer lado, se houver fundo","Entre duas boias vermelhas seguidas"],"correta":0,"explicacao":"No Brasil, que segue a Região B, quem entra no porto deixa a vermelha por boreste (direita) e a verde por bombordo (esquerda). Passar com a vermelha à esquerda deixaria você fora do canal.","referencia":"Sistema IALA · Região B"},{"id":"q-vermelha-saindo","cena":{"tipo":"canal","oculto":true,"sentido":"saindo"},"tipo":"multipla-escolha","enunciado":"Agora você está saindo do porto em direção ao mar. Por qual lado deixa as boias vermelhas?","opcoes":["Por bombordo, à minha esquerda","Por boreste, à minha direita","Por qualquer lado do canal","Saindo, não se usa boia vermelha"],"correta":0,"explicacao":"A regra das cores vale para quem entra. Saindo, tudo se inverte, por isso a vermelha fica por bombordo (esquerda) e a verde por boreste (direita).","referencia":"Sistema IALA · Região B"},{"id":"q-formato-verde","cena":{"tipo":"marcas","oculto":true},"tipo":"multipla-escolha","enunciado":"De longe, você não distingue a cor, mas vê o formato da boia. Na Região B, qual é o formato da marca de bombordo, a verde?","opcoes":["Cilíndrica, com tope em cilindro","Cônica, com tope em cone para cima","Pilar, com dois cones pretos no tope","Esférica, com listras vermelhas e brancas"],"correta":0,"explicacao":"A marca de bombordo é cilíndrica, como uma lata, e o tope dela também é um cilindro. A cônica, com cone de ponta para cima, é a de boreste, a vermelha. As outras duas opções são marcas que você vai ver nas próximas lições.","referencia":"Sistema IALA · Região B"}]},{"id":"balizamento-cardinais","temaId":"balizamento","titulo":"Marcas cardinais","descricao":"Como o tope, as cores e os lampejos mostram por onde passar","cartoes":[{"id":"c-cardinais","tipo":"conceito","titulo":"Marcas cardinais","texto":"Algumas boias não marcam um canal, e sim um perigo, como uma pedra ou um banco de areia. São as marcas cardinais, pretas e amarelas. O nome delas (Norte, Sul, Leste ou Oeste) diz de que lado está a água boa. Assim, você passa pelo lado do nome: numa cardinal Norte, passe ao norte dela.","falaMarujo":"Cardinal Norte? Passa pelo norte dela. Simples assim.","pose":"ensinando"},{"id":"c-cardinais-topes","tipo":"conceito","titulo":"O tope diz o nome","texto":"Para saber qual cardinal você está vendo, olhe o tope, os dois cones pretos no alto da boia. Na Norte, os dois apontam para cima, e na Sul, os dois apontam para baixo. Na Leste, um aponta para cima e o outro para baixo, com as bases juntas, formando um losango. Na Oeste, as pontas se encontram no meio, como uma ampulheta.","falaMarujo":"Cones pra cima, Norte. Cones pra baixo, Sul."},{"id":"c-cardinais-cores","tipo":"conceito","titulo":"As pontas mostram o preto","texto":"As cores da boia confirmam o tope, porque as pontas dos cones apontam para onde fica o preto. Por isso, a Norte é preta em cima e amarela embaixo, e a Sul é amarela em cima e preta embaixo. A Leste é preta com uma faixa amarela no meio, e a Oeste é amarela com uma faixa preta no meio.","falaMarujo":"Siga a ponta do cone e você acha o preto."},{"id":"c-cardinais-luzes","tipo":"conceito","titulo":"À noite, conte os lampejos","texto":"À noite, as cardinais acendem luz branca em lampejos (piscadas). Conte as piscadas e pense num relógio. A Leste dá 3 lampejos, como as 3 horas. A Sul dá 6 e mais um lampejo longo, como as 6 horas. A Oeste dá 9, como as 9 horas. Já a Norte, que fica no 12, pisca sem parar.","falaMarujo":"3, 6 e 9: Leste, Sul e Oeste no relógio."},{"id":"q-card-norte","tipo":"multipla-escolha","enunciado":"Você vê uma boia preta em cima e amarela embaixo, com dois cones pretos de ponta para cima no tope. Por onde você deve passar?","opcoes":["Pelo lado norte dela","Pelo lado sul dela","Por qualquer lado, com distância","Deixando-a por boreste, ao entrar"],"correta":0,"explicacao":"Cones de ponta para cima indicam a cardinal Norte, e a água boa fica ao norte dela. Por isso, você passa pelo norte. Passar pelo sul levaria você na direção do perigo.","referencia":"Balizamento IALA · Marcas cardinais"},{"id":"q-card-oeste","tipo":"multipla-escolha","enunciado":"No tope de uma boia preta e amarela, os dois cones pretos têm as pontas se encontrando no meio, como uma ampulheta. Que marca é essa?","opcoes":["Cardinal Oeste: passe a oeste dela","Cardinal Leste: passe a leste dela","Perigo isolado: mantenha distância","Águas seguras: pode se aproximar"],"correta":0,"explicacao":"Pontas que se encontram no meio formam a ampulheta da cardinal Oeste, por isso você passa a oeste dela. O losango, com as bases juntas no meio, é o tope da cardinal Leste.","referencia":"Balizamento IALA · Marcas cardinais"},{"id":"q-card-lampejos","tipo":"multipla-escolha","enunciado":"À noite, você vê uma boia com luz branca que dá 3 lampejos, apaga e repete. Qual cardinal é essa?","opcoes":["Cardinal Leste","Cardinal Norte","Cardinal Sul","Cardinal Oeste"],"correta":0,"explicacao":"Pense no relógio: as 3 horas ficam a leste, por isso 3 lampejos indicam a cardinal Leste. A Sul dá 6 lampejos e um longo, a Oeste dá 9 e a Norte pisca sem parar.","referencia":"Balizamento IALA · Marcas cardinais"}]},{"id":"balizamento-outras-marcas","temaId":"balizamento","titulo":"Outras marcas","descricao":"Perigo isolado, águas seguras e marca especial: o que cada uma avisa","cartoes":[{"id":"c-outras-marcas","tipo":"conceito","titulo":"Perigo isolado","texto":"Às vezes o perigo é pequeno, como uma pedra solta, e tem água navegável em toda a volta. Ali fica a marca de perigo isolado, preta com faixas vermelhas horizontais e tope de duas esferas pretas. Ela está em cima do perigo, por isso dê boa distância. À noite, ela mostra luz branca com 2 lampejos.","falaMarujo":"Duas bolas pretas: tem coisa embaixo, fique longe.","pose":"ensinando"},{"id":"c-aguas-seguras","tipo":"conceito","titulo":"Águas seguras","texto":"Nem toda boia avisa de perigo. A marca de águas seguras tem listras verticais vermelhas e brancas e tope de uma esfera vermelha. Ela indica que há água navegável em toda a volta e é comum na entrada de um canal.\n\nÀ noite, a luz é branca. Ela pode ser isofásica (acesa e apagada pelo mesmo tempo), de ocultação (mais tempo acesa do que apagada), de um lampejo longo ou em Morse A (um lampejo curto e um longo).","falaMarujo":"Listra em pé, vermelha e branca: água boa em volta."},{"id":"c-marca-especial","tipo":"conceito","titulo":"Marca especial","texto":"Algumas boias não guiam a navegação, e sim avisam de uma área ou estrutura especial, como mergulho, esporte ou cabo submarino. É a marca especial, amarela e com tope em X amarelo. À noite, a luz dela também é amarela. Para saber o que ela marca, consulte a carta náutica.","falaMarujo":"Amarela com X: tem algo especial ali."},{"id":"q-perigo-isolado","tipo":"multipla-escolha","enunciado":"Você vê uma boia preta com faixas vermelhas horizontais e duas esferas pretas no tope. O que ela indica?","opcoes":["Um perigo pequeno embaixo dela, com água navegável em volta","O meio do canal, onde se passa colado nela","Uma área de mergulho ou de esporte náutico","O fim do canal balizado e do fundo seguro"],"correta":0,"explicacao":"É a marca de perigo isolado. Ela fica em cima de uma pedra, casco afundado ou baixio pequeno, por isso você pode passar por qualquer lado, desde que mantenha boa distância. Passar colado nela é justamente o erro.","referencia":"Balizamento IALA · Marca de perigo isolado"},{"id":"q-aguas-seguras","tipo":"multipla-escolha","enunciado":"Você vê uma boia com listras verticais vermelhas e brancas e uma esfera vermelha no tope. O que ela significa?","opcoes":["Águas seguras: há água navegável em toda a volta","Perigo isolado: não se aproxime dela","Marca lateral de boreste do canal","Cardinal Sul: passe ao sul dela"],"correta":0,"explicacao":"É a marca de águas seguras, que indica água navegável em toda a volta e costuma marcar o início ou o meio do canal. Ela não avisa de perigo: a de perigo isolado é preta com faixas vermelhas horizontais.","referencia":"Balizamento IALA · Marca de águas seguras"},{"id":"q-especial","tipo":"multipla-escolha","enunciado":"Perto da praia, você vê uma boia amarela com um X amarelo no tope. O que ela marca?","opcoes":["Uma área especial, como mergulho, esporte ou cabo submarino","Um perigo isolado, com água navegável em volta","O lado de bombordo do canal de entrada","O lado de boreste do canal de entrada"],"correta":0,"explicacao":"É a marca especial. Ela não guia a navegação, e sim avisa de uma área ou estrutura especial. Para saber qual, consulte a carta náutica.","referencia":"Balizamento IALA · Marcas especiais"},{"id":"q-verde-saindo","cena":{"tipo":"canal","oculto":true,"sentido":"saindo"},"tipo":"multipla-escolha","enunciado":"Você está saindo do porto em direção ao mar, no Brasil (Região B). Por qual lado deixa as boias verdes?","opcoes":["Por boreste, à minha direita","Por bombordo, à minha esquerda","Por qualquer lado do canal","Entre duas boias verdes seguidas"],"correta":0,"explicacao":"Entrando, a verde fica por bombordo (esquerda). Saindo, tudo se inverte, por isso a verde fica por boreste (direita) e a vermelha por bombordo.","referencia":"Balizamento IALA · Região B"}]},{"id":"governo-quem-da-passagem","temaId":"governo","titulo":"Quem dá passagem?","descricao":"Quem desvia quando duas embarcações se encontram de frente, cruzando ou ultrapassando","cartoes":[{"id":"c-roda-a-roda","cena":{"tipo":"encontro","sinal":"guinando-boreste","manobra":"boreste","vocePara":"boreste"},"tipo":"conceito","titulo":"Roda a roda","texto":"Quando duas embarcações de propulsão mecânica (a motor) vêm de frente, em rumos opostos ou quase, há risco de abalroamento (colisão). Essa situação se chama roda a roda. Nela, as duas guinam (viram) para boreste (direita) e passam bombordo com bombordo, ou seja, cada uma passa pela esquerda da outra.","falaMarujo":"De frente? Os dois pra boreste e ninguém se arranha."},{"id":"c-roda-a-roda-noite","tipo":"conceito","titulo":"Roda a roda à noite","texto":"À noite, você reconhece o roda a roda pelas luzes. Você vê as luzes de mastro da outra embarcação (as luzes brancas no alto) alinhadas, uma atrás da outra, ou quase, e ao mesmo tempo as duas luzes de bordo, a vermelha e a verde. Isso quer dizer que ela vem bem de frente para você.","falaMarujo":"Vermelha e verde juntas? Ela vem de frente."},{"id":"q-roda-a-roda","cena":{"tipo":"encontro","sinal":"guinando-boreste","manobra":"boreste","vocePara":"boreste"},"tipo":"multipla-escolha","enunciado":"Você está de lancha e um navio a motor vem bem pela sua proa, em rumo oposto ao seu. O que as duas embarcações devem fazer?","opcoes":["As duas guinam para boreste","As duas guinam para bombordo","A menor para e a maior segue","Cada uma guina para onde quiser"],"correta":0,"explicacao":"Isso é roda a roda: as duas guinam para boreste (direita) e passam bombordo com bombordo, avisando com 1 apito curto. A menor não fica parada esperando, porque a regra vale para as duas.","referencia":"RIPEAM · Regra 14"},{"id":"c-rumos-cruzados","cena":{"tipo":"luzes-noite","aspecto":290,"embarcacao":{"tipo":"propulsao-mecanica"}},"tipo":"conceito","titulo":"Rumos cruzados","texto":"Quando duas embarcações a motor têm rumos que se cruzam, com risco de colisão, quem manobra é a que vê a outra pelo seu boreste (direita). Se possível, ela também evita cruzar pela proa (a frente) da outra. À noite, você sabe que é a sua vez de manobrar quando vê a luz vermelha da outra embarcação.","falaMarujo":"Viu vermelho? É você quem manobra!"},{"id":"q-cruzado-luz","cena":{"tipo":"luzes-noite","aspecto":290,"embarcacao":{"tipo":"propulsao-mecanica"}},"tipo":"multipla-escolha","enunciado":"À noite, seu rumo se cruza com o de outra embarcação a motor, e você vê a luz branca e a luz vermelha dela. Quem manobra?","opcoes":["Você, porque ela está pelo seu boreste","Ela, porque você está pelo boreste dela","Quem estiver mais rápido no momento","Ninguém, os dois mantêm o rumo"],"correta":0,"explicacao":"Ver a luz vermelha dela significa que ela cruza pelo seu boreste, por isso é você quem manobra. De preferência, guine para boreste e passe pela popa (a parte de trás) dela.","referencia":"RIPEAM · Regras 15 e 16"},{"id":"c-quem-mantem","tipo":"conceito","titulo":"Quem tem a preferência","texto":"Nos rumos cruzados, quem tem a preferência mantém rumo e velocidade, para a outra embarcação poder calcular a manobra. Se você tem a preferência e percebe que a outra não está manobrando, pode manobrar por conta própria. E, quando a colisão não puder mais ser evitada só pela manobra da outra, você é obrigado a agir.","falaMarujo":"Preferência não é licença pra bater.","pose":"ensinando"},{"id":"q-mantem-rumo","tipo":"multipla-escolha","enunciado":"Seu rumo cruza com o de outra embarcação a motor, e a preferência é sua. O que você deve fazer?","opcoes":["Manter rumo e velocidade, vigiando, e agir se a outra não manobrar","Acelerar para passar logo pela proa da outra embarcação","Parar as máquinas para garantir que nada aconteça","Guinar para bombordo para facilitar a manobra da outra"],"correta":0,"explicacao":"Quem tem a preferência mantém rumo e velocidade, para a outra poder calcular a manobra. Mas preferência não dá direito de bater: se a outra não age, você age. E evite guinar para bombordo quando a outra estiver pelo seu bombordo.","referencia":"RIPEAM · Regra 17"},{"id":"c-preferencias","tipo":"conceito","titulo":"Quem ultrapassa desvia","texto":"Na ultrapassagem, você vem por trás de outra embarcação e vai passar à frente dela. Nesse caso, quem ultrapassa sempre se mantém fora do caminho de quem é ultrapassado. Não importa se um é veleiro e o outro é a motor: quem chega por trás é quem desvia.","falaMarujo":"Chegou por trás? O desvio é seu.","pose":"ensinando"},{"id":"q-ultrapassagem","tipo":"multipla-escolha","enunciado":"Sua lancha é mais rápida e vai ultrapassar um veleiro que segue à sua frente, no mesmo rumo. Quem deve se manter fora do caminho?","opcoes":["Você, que está ultrapassando","O veleiro, porque é mais lento","O veleiro, se estiver usando motor","Ninguém, até ficarem lado a lado"],"correta":0,"explicacao":"Quem ultrapassa se mantém fora do caminho de quem é ultrapassado até ficar safo (livre) e bem afastado. Isso vale seja quem for o ultrapassado, veleiro ou embarcação a motor.","referencia":"RIPEAM · Regra 13"},{"id":"c-preferencias-lancha","tipo":"conceito","titulo":"A lancha dá caminho a quase todos","texto":"Fora da ultrapassagem, existe uma ordem de preferência. Sua lancha a motor dá caminho a quatro tipos de embarcação: a sem governo (que não consegue manobrar, por exemplo por avaria), a com manobra restrita (que faz um trabalho que limita a manobra, como uma draga), a que está pescando e o veleiro.","falaMarujo":"Lancha cede a sem governo, restrita, pesca e vela."},{"id":"c-preferencias-vela-pesca","tipo":"conceito","titulo":"Veleiro e pesqueiro também cedem","texto":"A mesma ordem vale entre os outros barcos. O veleiro dá caminho a quem está sem governo, com manobra restrita ou pescando. O pesqueiro dá caminho a quem está sem governo ou com manobra restrita. Aqui, pescando é só quem usa rede ou aparelho que restringe a manobra, por isso quem pesca de corrico (linha arrastada) não conta.","falaMarujo":"Quanto menos manobra, mais preferência."},{"id":"c-governo-canal-estreito","tipo":"conceito","titulo":"Em canal estreito","texto":"Num canal estreito, alguns navios só conseguem navegar com segurança ali dentro. Por isso, embarcações com menos de 20 m e veleiros não devem atrapalhar a passagem deles. O pesqueiro tem uma regra ainda mais ampla: não deve atrapalhar nenhuma embarcação que navega no canal. Ou seja, de lancha num canal estreito, deixe o caminho livre para quem depende dele.","falaMarujo":"Canal estreito: o pequeno abre caminho."},{"id":"q-lancha-veleiro","cena":{"tipo":"luzes-noite","aspecto":0,"embarcacao":{"tipo":"vela"}},"tipo":"multipla-escolha","enunciado":"À noite, você está de lancha e vê à sua proa um barco com a luz vermelha e a verde juntas, sem nenhuma luz branca acima delas. Quem dá passagem?","opcoes":["A sua lancha","O veleiro","As duas, guinando para boreste","A embarcação maior"],"correta":0,"explicacao":"Sem a luz de mastro, a branca alta, esse barco é um veleiro. A lancha a motor se mantém fora do caminho dele, a não ser que esteja sendo ultrapassada por ele. O roda a roda, em que as duas guinam para boreste, vale só entre duas embarcações a motor.","referencia":"RIPEAM · Regra 18(a)"}]},{"id":"governo-risco-veleiros","temaId":"governo","titulo":"Risco de colisão e veleiros","descricao":"Como saber se há risco de colisão, como manobrar e quem cede entre veleiros","cartoes":[{"id":"c-risco-colisao","tipo":"conceito","titulo":"Marcação constante é perigo","texto":"Para saber se há risco de colisão, observe a marcação, ou seja, a direção em que você vê a outra embarcação. Se a marcação não muda de forma apreciável e a distância diminui, há risco. Às vezes há risco mesmo com a marcação mudando, como diante de um navio grande, de um reboque ou de uma embarcação muito perto. Na dúvida, considere que há risco.","falaMarujo":"Se ela não anda no seu para-brisa e só cresce, vai bater!","pose":"ensinando"},{"id":"c-manobra-ampla","tipo":"conceito","titulo":"Manobre grande e cedo","texto":"Quando for desviar, faça uma manobra ampla, a tempo e bem visível para a outra embarcação. Assim, ela percebe logo o que você está fazendo. Já várias pequenas mudanças de rumo confundem, porque a outra embarcação não nota que você desviou.","falaMarujo":"Desviou? Que seja grande, cedo e bem visível.","pose":"ensinando"},{"id":"c-veleiros","tipo":"conceito","titulo":"Veleiro com veleiro","texto":"Entre dois veleiros com risco de colisão, quem dá passagem depende do vento. Quando eles recebem o vento por bordos diferentes, ou seja, um pela direita e o outro pela esquerda, quem recebe o vento por bombordo (esquerda) dá passagem.","falaMarujo":"Vento entrando pela esquerda? Você cede.","pose":"ensinando"},{"id":"c-veleiros-barlavento","tipo":"conceito","titulo":"Vento pelo mesmo bordo","texto":"Quando os dois veleiros recebem o vento pelo mesmo bordo, quem está a barlavento (do lado de onde vem o vento) dá passagem a quem está a sotavento (do outro lado). E, como sempre, quem ultrapassa cede.","falaMarujo":"Mais perto do vento? Você cede."},{"id":"c-veleiros-duvida","tipo":"conceito","titulo":"Na dúvida, ceda","texto":"Às vezes você não consegue ver por qual bordo o outro veleiro recebe o vento. Se o seu recebe o vento por bombordo, o outro está a barlavento e você não sabe o bordo dele, quem dá passagem é você.","falaMarujo":"Não sabe o vento do outro? Ceda você.","pose":"pensando"},{"id":"q-marcacao","tipo":"multipla-escolha","enunciado":"Você mantém o rumo, e uma embarcação que cruza seu caminho continua sempre na mesma direção em relação a você, cada vez maior. O que isso indica?","opcoes":["Que há risco de colisão","Que ela vai passar pela sua popa","Que ela está parada, fundeada","Nada, enquanto ela estiver longe"],"correta":0,"explicacao":"A marcação não muda e a distância diminui, e esse é o sinal clássico de risco de colisão. Por isso, aja cedo: esperar ela chegar perto só reduz o seu tempo de manobra.","referencia":"RIPEAM · Regra 7"},{"id":"q-manobra-ampla","tipo":"multipla-escolha","enunciado":"Você percebeu risco de colisão e precisa desviar de outra embarcação. Qual é a manobra certa?","opcoes":["Uma mudança ampla, feita com antecedência e bem visível","Várias pequenas correções de rumo, uma após a outra","Esperar até o último momento para ver o que ela faz","Acelerar bastante e passar pela proa da outra"],"correta":0,"explicacao":"A manobra deve ser clara, feita a tempo e grande o bastante para o outro perceber. Pequenas mudanças seguidas não são notadas e deixam o outro em dúvida.","referencia":"RIPEAM · Regra 8"},{"id":"q-veleiros-bordos","tipo":"multipla-escolha","enunciado":"Seu veleiro e outro se aproximam com risco de colisão, sem que um ultrapasse o outro. O seu recebe o vento por bombordo e o outro, por boreste. Quem dá passagem?","opcoes":["O seu, que recebe o vento por bombordo","O outro, que recebe o vento por boreste","O que estiver mais rápido no momento","Os dois, guinando para boreste"],"correta":0,"explicacao":"Com o vento por bordos diferentes, quem recebe o vento por bombordo se mantém fora do caminho do outro. Guinar os dois para boreste é a regra do roda a roda, que vale entre embarcações a motor.","referencia":"RIPEAM · Regra 12(a)(i)"},{"id":"q-veleiros-barlavento","tipo":"multipla-escolha","enunciado":"Seu veleiro e outro se aproximam com risco de colisão, sem ultrapassagem, e os dois recebem o vento pelo mesmo bordo. Você está a barlavento do outro. Quem dá passagem?","opcoes":["Você, que está a barlavento","O outro, que está a sotavento","O veleiro que for maior","Ninguém, os dois mantêm o rumo"],"correta":0,"explicacao":"Com o vento pelo mesmo bordo, quem está a barlavento (do lado de onde vem o vento) se mantém fora do caminho de quem está a sotavento.","referencia":"RIPEAM · Regra 12(a)(ii)"}]},{"id":"nos-arremate-emendas","temaId":"marinharia","titulo":"Nós I: arremate e emendas","descricao":"Nó de oito para a ponta do cabo, nó direito e nó de escota para emendar","cartoes":[{"id":"c-chicote-firme","tipo":"conceito","titulo":"Duas palavras antes dos nós","texto":"Para aprender nós, você precisa conhecer duas partes do cabo (o nome que se dá à corda a bordo). O chicote é a ponta do cabo, a parte com que você dá o nó. O firme é o resto do cabo, ou seja, a parte que aguenta o esforço.","falaMarujo":"Chicote é a ponta. Firme é o que faz força.","pose":"ensinando"},{"id":"c-oito","cena":{"no":"oito","tipo":"no"},"tipo":"conceito","texto":"Alguns cabos passam por um moitão (um bloco com roldana), por uma argola ou por um olhal (um furo com reforço). Se a ponta escapar, você perde o cabo. Por isso existe o nó de arremate, feito no chicote. O mais usado é o nó de oito: ele engrossa a ponta, que assim não passa pelo furo.","titulo":"Nó de oito","falaMarujo":"Um oito no chicote, e o cabo não foge."},{"id":"c-direito","cena":{"no":"direito","tipo":"no"},"pose":"orgulhoso","tipo":"conceito","texto":"Emendar é unir dois cabos um ao outro. Quando os dois têm a mesma bitola, ou seja, a mesma grossura, use o nó direito. Mas ele pode desatar quando a emenda faz muita força, por isso serve para esforços pequenos.\n\nO nó direito também serve para rizar a vela, que é amarrar parte do pano para diminuir a vela quando venta forte.","titulo":"Nó direito","falaMarujo":"Mesma grossura? Nó direito."},{"id":"c-escota","cena":{"no":"escota","tipo":"no"},"pose":"pensando","tipo":"conceito","texto":"Quando os dois cabos têm bitolas diferentes, ou seja, um é grosso e o outro é fino, use o nó de escota. O cabo mais grosso forma o seio, que é uma alça em U. O mais fino passa por dentro dessa alça, dá a volta nela e passa por baixo de si mesmo.\n\nSe a emenda vai fazer muito esforço, use o nó de escota dobrado, com uma volta a mais em torno da alça.","titulo":"Nó de escota","falaMarujo":"O grosso faz a alça; o fino abraça e morde a si mesmo."},{"id":"q-id-oito","cena":{"no":"oito","tipo":"no"},"tipo":"multipla-escolha","opcoes":["Nó de oito","Nó direito","Lais de guia","Volta do fiel"],"correta":0,"enunciado":"Este nó foi dado na ponta de um cabo, para ela não escapar de uma argola. Que nó é este?","explicacao":"É o nó de oito, um nó de arremate: ele engrossa a ponta do cabo para ela não escapar de um moitão ou de uma argola.","referencia":"Marinharia · nós de arremate"},{"id":"q-uso-direito","cena":{"no":"direito","tipo":"no","oculto":true},"tipo":"multipla-escolha","opcoes":["Nó direito","Nó de escota","Nó de oito","Volta de cunho"],"correta":0,"enunciado":"Você precisa emendar dois cabos da mesma bitola, ou seja, da mesma grossura. Qual nó usar?","explicacao":"Para emendar cabos da mesma bitola, o nó certo é o nó direito. Se as grossuras fossem diferentes, aí sim o certo seria o nó de escota.","referencia":"Marinharia · emendas"},{"id":"q-uso-escota","cena":{"no":"escota","tipo":"no","oculto":true},"tipo":"multipla-escolha","opcoes":["Nó de escota","Nó direito","Lais de guia","Nó de oito"],"correta":0,"enunciado":"Você precisa emendar, com segurança, um cabo grosso a um cabo fino. Qual nó usar?","explicacao":"O nó de escota une cabos de bitolas diferentes: o grosso forma o seio e o fino dá a volta nele e passa por baixo de si mesmo. O nó direito é para cabos da mesma grossura.","referencia":"Marinharia · emendas"},{"id":"q-uso-oito","cena":{"no":"oito","tipo":"no","oculto":true},"tipo":"multipla-escolha","opcoes":["Nó de oito","Volta do fiel","Nó de escota","Volta de cunho"],"correta":0,"enunciado":"Você quer que o cabo não escape do moitão (o bloco com roldana). Que nó você dá no chicote, a ponta do cabo?","explicacao":"O nó de oito é o arremate clássico: segura bem a ponta e se desfaz fácil, mesmo depois de apertado.","referencia":"Marinharia · nós de arremate"},{"id":"q-id-escota","cena":{"no":"escota","tipo":"no"},"tipo":"multipla-escolha","opcoes":["Nó de escota","Nó direito","Volta do fiel","Lais de guia"],"correta":0,"enunciado":"Na imagem, dois cabos de grossuras diferentes estão unidos por um nó. Que nó é este?","explicacao":"É o nó de escota. Repare que um cabo forma uma alça em U e o outro abraça essa alça, passando por baixo de si mesmo.","referencia":"Marinharia · emendas"}]},{"id":"nos-alcas-voltas","temaId":"marinharia","titulo":"Nós II: alças e voltas","descricao":"Lais de guia para fazer alça, volta do fiel e volta de cunho para prender o cabo","cartoes":[{"id":"c-lais","cena":{"no":"lais-de-guia","tipo":"no"},"tipo":"conceito","texto":"Às vezes você precisa de uma alça na ponta do cabo, por exemplo para passar num cabeço, o poste de amarração do cais. O nó que faz essa alça é o lais de guia. Faça uma pequena volta no firme: é a toca. O chicote é o coelho: ele sai pela toca, dá a volta no firme, que é a árvore, e volta pela toca. A alça fica fixa: não corre nem aperta.","titulo":"Lais de guia","falaMarujo":"O coelho sai da toca, dá a volta na árvore e volta pra toca."},{"id":"c-lais-salvamento","tipo":"conceito","titulo":"O nó do salvamento","texto":"Como a alça do lais de guia não aperta, ele é o nó do salvamento. Você passa a alça em volta do corpo de uma pessoa, por baixo dos braços, e consegue içá-la, ou seja, puxá-la para cima, sem estrangular ninguém.","falaMarujo":"Alça que não aperta é a que tira gente da água.","pose":"ensinando"},{"id":"c-fiel","cena":{"no":"volta-do-fiel","tipo":"no"},"pose":"aprovando","tipo":"conceito","texto":"A defensa é a peça macia que fica pendurada do lado da lancha e protege o casco quando ela encosta no cais. Para pendurá-la, use a volta do fiel: dê duas voltas no balaústre (as colunas da grade na borda da lancha), cruzando o cabo, e passe o chicote por baixo dessa cruz.\n\nEla é rápida de dar e deixa você ajustar a altura com facilidade. Mas pode correr com o balanço, por isso confira de vez em quando.","titulo":"Volta do fiel","falaMarujo":"Duas voltas e o chicote por baixo da cruz. Defensa no lugar!"},{"id":"c-cunho","cena":{"no":"volta-de-cunho","tipo":"no"},"pose":"ensinando","tipo":"conceito","texto":"O cunho é a peça com duas orelhas, no cais ou na lancha, onde você prende o cabo de amarração. Para isso, use a volta de cunho.\n\nComece com uma volta redonda na base, pela orelha mais distante de onde vem a força. Depois, cruze o cabo em oito sobre as orelhas e termine com um cote mordido, uma volta em que o cabo passa por baixo de si mesmo e trava tudo.","titulo":"Volta de cunho","falaMarujo":"Comece sempre pela orelha mais distante de onde vem a força."},{"id":"q-id-lais","cena":{"no":"lais-de-guia","tipo":"no"},"tipo":"multipla-escolha","opcoes":["Lais de guia","Nó de oito","Volta do fiel","Nó direito"],"correta":0,"enunciado":"Este nó forma uma alça fixa na ponta do cabo. Que nó é este?","explicacao":"É o lais de guia: a alça não corre nem aperta, e o nó é fácil de desfazer depois.","referencia":"Marinharia · alças"},{"id":"q-uso-lais","cena":{"no":"lais-de-guia","tipo":"no","oculto":true},"tipo":"multipla-escolha","opcoes":["Lais de guia","Volta do fiel","Nó de oito","Nó direito"],"correta":0,"enunciado":"Homem ao mar! Você vai jogar um cabo para a vítima, com uma alça que não aperte em volta do corpo dela. Qual nó faz essa alça?","explicacao":"A alça do lais de guia é fixa, por isso não estrangula a pessoa quando o cabo é puxado. É o nó do salvamento. Lembre: primeiro jogue a boia salva-vidas, e a alça vai por baixo dos braços.","referencia":"Marinharia · resgate de homem ao mar"},{"id":"q-uso-cunho","cena":{"no":"volta-de-cunho","tipo":"no","oculto":true},"tipo":"multipla-escolha","opcoes":["Volta de cunho","Nó de escota","Nó direito","Nó de oito"],"correta":0,"enunciado":"Você está atracando no cais. Como prende o cabo de amarração no cunho?","explicacao":"O cabo de amarração se prende no cunho com a volta de cunho: uma volta redonda, voltas cruzadas em oito sobre as orelhas e um cote mordido para travar.","referencia":"Marinharia · amarração"},{"id":"q-uso-fiel","cena":{"no":"volta-do-fiel","tipo":"no","oculto":true},"tipo":"multipla-escolha","opcoes":["Volta do fiel","Lais de guia","Nó de escota","Nó direito"],"correta":0,"enunciado":"Você quer pendurar rapidamente a defensa no balaústre. Que volta usar?","explicacao":"A volta do fiel é rápida de dar e permite ajustar a altura, por isso é perfeita para defensas. Ela pode correr com o balanço; para ficar de vez, arremate com um cote.","referencia":"Marinharia · voltas"},{"id":"q-id-cunho","cena":{"no":"volta-de-cunho","tipo":"no"},"tipo":"multipla-escolha","opcoes":["Volta de cunho","Volta do fiel","Nó de oito","Lais de guia"],"correta":0,"enunciado":"Na imagem, o cabo está preso numa peça com duas orelhas. Como se chama essa amarração?","explicacao":"É a volta de cunho: o cabo cruza em oito sobre as orelhas do cunho, e o cote final trava tudo.","referencia":"Marinharia · amarração"}]},{"id":"nos-na-pratica","temaId":"marinharia","titulo":"Nós III: na prática","descricao":"Como escolher o nó certo em cada situação a bordo","cartoes":[{"id":"c-no-certo","pose":"ensinando","tipo":"conceito","texto":"Cada nó tem uma função, por isso a escolha começa pela pergunta: o que você precisa fazer? Pode ser emendar dois cabos, fazer uma alça ou prender o cabo num poste, num balaústre ou no cunho. A resposta escolhe o nó. Assim, ele segura quando precisa e desata quando você quer.","titulo":"O nó certo na hora certa","falaMarujo":"Primeiro a situação, depois o nó."},{"id":"q-sit-reboque","cena":{"no":"escota","tipo":"no","oculto":true},"tipo":"multipla-escolha","opcoes":["Nó de escota","Nó direito","Nó de oito","Volta do fiel"],"correta":0,"enunciado":"Você vai rebocar um caiaque. O cabo da lancha é grosso e o do caiaque é fino. Como emendar os dois?","explicacao":"Bitolas diferentes pedem o nó de escota: o grosso faz o seio e o fino passa por ele. Com grossuras diferentes, o nó direito correria.","referencia":"Marinharia · Nós de emenda"},{"id":"q-sit-cabeco","cena":{"no":"lais-de-guia","tipo":"no","oculto":true},"tipo":"multipla-escolha","opcoes":["Lais de guia","Nó direito","Volta de cunho","Nó de escota"],"correta":0,"enunciado":"Chegando ao cais, você quer jogar uma alça já pronta no cabeço (o poste de amarração) para prender a lancha. Que nó faz essa alça?","explicacao":"O lais de guia faz uma alça fixa, que não corre nem aperta. Além disso, ele desata fácil mesmo depois de ter feito força.","referencia":"Marinharia · Alças"},{"id":"q-sit-defensa","cena":{"no":"volta-do-fiel","tipo":"no","oculto":true},"tipo":"multipla-escolha","opcoes":["Volta do fiel","Volta de cunho","Lais de guia","Nó de escota"],"correta":0,"enunciado":"Antes de encostar no cais, você precisa ajustar rápido a altura das defensas no balaústre. Que volta usar?","explicacao":"A volta do fiel é rápida de dar e fácil de ajustar. Só confira de vez em quando, porque ela pode correr se o esforço mudar de lado.","referencia":"Marinharia · Voltas"},{"id":"q-sit-cunho","cena":{"no":"volta-de-cunho","tipo":"no","oculto":true},"tipo":"multipla-escolha","opcoes":["Uma volta redonda, voltas em oito e um cote mordido","Um nó de oito dado no meio do cabo","Um nó direito dado em volta do cunho","Várias voltas redondas, sem nenhum cote"],"correta":0,"enunciado":"A lancha já está encostada e você vai prender o cabo de amarração no cunho do píer. Como fazer?","explicacao":"Use a volta de cunho: uma volta redonda pela orelha mais distante, voltas cruzadas em oito e um cote mordido para travar. Ela segura bem e solta rápido.","referencia":"Marinharia · Volta de cunho"},{"id":"q-sit-moitao","cena":{"no":"oito","tipo":"no","oculto":true},"tipo":"multipla-escolha","opcoes":["Nó de oito","Lais de guia","Volta do fiel","Nó direito"],"correta":0,"enunciado":"A escota (o cabo que controla a vela) passa por um moitão. Se ela escapar do moitão, a vela fica solta. Que nó dar no chicote da escota?","explicacao":"O nó de oito faz um calombo no chicote que não passa pelo moitão, e é fácil de desfazer depois.","referencia":"Marinharia · Nós de arremate"},{"id":"q-sit-rizar","cena":{"no":"direito","tipo":"no","oculto":true},"tipo":"multipla-escolha","opcoes":["Nó direito","Nó de escota","Volta de cunho","Nó de oito"],"correta":0,"enunciado":"Ventou forte e você vai rizar a vela, amarrando o pano em volta da retranca (a vara que prende a base da vela) com os dois chicotes do mesmo cabinho. Qual nó usar?","explicacao":"Os rizes, os cabinhos que prendem o pano rizado, se amarram com nó direito. Ele é plano, une pontas da mesma bitola e se solta fácil na hora de desfazer os rizes e devolver o pano à vela. Como pode desatar sob muita força, ele não é o nó para emendas de grande esforço.","referencia":"Marinharia · Nó direito"},{"id":"q-sit-errado","cena":{"no":"direito","tipo":"no","oculto":true},"tipo":"multipla-escolha","opcoes":["Nó direito","Nó de escota simples","Nó de escota dobrado"],"correta":0,"enunciado":"Você vai emendar dois cabos de grossuras bem diferentes, e a emenda vai aguentar muito esforço. Qual destes nós você deve evitar?","explicacao":"O nó direito é o que deve ser evitado: com bitolas diferentes, ele desliza e pode se desfazer sob esforço. O certo é o nó de escota. Para mais segurança, use o nó de escota dobrado, em que o cabo fino dá duas voltas em torno da alça em vez de uma.","referencia":"Marinharia · Nós de emenda"}]},{"id":"salvatagem-seguranca","temaId":"salvatagem","titulo":"Segurança a bordo","descricao":"Coletes, boia salva-vidas e o extintor certo para cada tipo de fogo","cartoes":[{"id":"c-coletes","tipo":"conceito","texto":"Se alguém cair na água, é o colete salva-vidas que mantém a pessoa boiando. Por isso, a lancha precisa ter um colete aprovado para cada pessoa a bordo, do tamanho certo. Ele deve ficar em lugar de fácil acesso, nunca trancado no paiol, o compartimento onde se guardam coisas.","titulo":"Colete para todos","falaMarujo":"Colete no paiol não salva ninguém. Deixa à mão!"},{"id":"c-colete-vestido","tipo":"conceito","titulo":"Quem navega de colete","texto":"Algumas pessoas devem navegar já vestindo o colete. Por segurança, isso vale para crianças e para quem não sabe nadar. Na moto aquática (o jet ski), o colete vestido é obrigatório para todos a bordo, ou seja, para o condutor e para quem vai na garupa.","falaMarujo":"Criança, quem não nada e jet ski: colete no corpo.","pose":"aprovando"},{"id":"c-boia","tipo":"conceito","titulo":"Boia pronta para jogar","texto":"Além dos coletes, deixe à mão a boia circular com retinida, que é um cabo leve preso à boia. Ela fica pronta para ser jogada a quem cair na água. Assim, a pessoa se agarra à boia e você a puxa pela retinida.","falaMarujo":"Boia guardada não alcança ninguém."},{"id":"c-extintores","pose":"ensinando","tipo":"conceito","texto":"Nem todo fogo se apaga do mesmo jeito. Os incêndios são divididos em classes, conforme o que está queimando, e cada classe pede um extintor certo.\n\nA classe A é a dos sólidos que deixam brasa, como madeira, papel e tecido. Nela, água e espuma servem.","titulo":"Cada fogo, seu extintor","falaMarujo":"Classe A deixa brasa: água e espuma resolvem."},{"id":"c-fogo-classe-b","tipo":"conceito","titulo":"Fogo em combustível","texto":"A classe B é a dos líquidos inflamáveis, como gasolina, diesel e óleo. Nesse fogo, nunca use jato de água, porque ele espalha o líquido em chamas. Use pó químico, CO2 ou espuma.","falaMarujo":"Combustível em chamas? Jato de água, jamais.","pose":"bravo"},{"id":"c-fogo-classe-c","tipo":"conceito","titulo":"Fogo elétrico","texto":"A classe C é a do equipamento elétrico ligado, como o painel da lancha. Água conduz eletricidade e pode dar choque, por isso nunca use água. Corte a energia e use CO2 ou pó químico.\n\nO pó químico ABC serve nas três classes.","falaMarujo":"Fogo elétrico: corte a energia, depois CO2 ou pó.","pose":"ensinando"},{"id":"q-extintor-b","tipo":"multipla-escolha","opcoes":["Extintor de pó químico ou de CO2","Mangueira com água em jato","Balde com água do mar","Qualquer extintor que estiver à mão"],"correta":0,"enunciado":"O combustível derramado perto do motor pegou fogo. Qual extintor usar?","explicacao":"Combustível em chamas é fogo classe B, que se combate com pó químico, CO2 ou espuma. Água em jato espalha o líquido em chamas. Se puder, corte também a alimentação de combustível.","referencia":"Combate a incêndio · Classes de fogo"},{"id":"q-extintor-c","tipo":"multipla-escolha","opcoes":["Cortar a energia e usar CO2 ou pó químico","Jogar água para resfriar o painel rápido","Abrir o painel para ventilar o fogo","Usar o extintor de água pressurizada"],"correta":0,"enunciado":"Está saindo fumaça e fogo do painel elétrico, que está ligado. O que fazer?","explicacao":"Equipamento elétrico ligado é fogo classe C, por isso você corta a energia e usa CO2 ou pó químico. Água conduz eletricidade e pode dar choque.","referencia":"Combate a incêndio · Classes de fogo"}]},{"id":"salvatagem-homem-ao-mar","temaId":"salvatagem","titulo":"Homem ao mar!","descricao":"O que fazer, passo a passo, quando alguém cai da lancha","cartoes":[{"id":"c-homem-ao-mar","pose":"apito","tipo":"conceito","texto":"Uma pessoa no mar some de vista muito rápido, por isso os primeiros segundos contam. Assim que alguém cair, grite “homem ao mar por boreste” (direita) ou “por bombordo” (esquerda), conforme o lado da queda. Ao mesmo tempo, jogue a boia.","titulo":"Homem ao mar!","falaMarujo":"Gritou e jogou a boia: as duas coisas na hora!"},{"id":"c-hom-apontador","tipo":"conceito","titulo":"Alguém não tira os olhos","texto":"Logo depois do alarme, uma pessoa a bordo fica só com uma tarefa: apontar para quem caiu, sem tirar os olhos dela. Assim, quem está pilotando sabe sempre para onde ir.","falaMarujo":"Quem aponta não pisca. Perdeu de vista no mar, é difícil achar.","pose":"apito"},{"id":"q-hom-primeiro","tipo":"multipla-escolha","opcoes":["Dar o alarme, jogar a boia e manter alguém apontando","Pular na água para ajudar a pessoa a boiar","Parar o motor e esperar a pessoa nadar até você","Dar ré na direção da pessoa para chegar rápido"],"correta":0,"enunciado":"Alguém caiu pelo lado de boreste da sua lancha. Qual é a primeira coisa a fazer?","explicacao":"O certo é dar o alarme, jogar a boia e deixar alguém apontando para a pessoa. Pular na água costuma virar duas vítimas, e dar ré na direção dela a coloca perto do hélice.","referencia":"Salvatagem · Homem ao mar"},{"id":"c-hom-helice","tipo":"conceito","titulo":"Afaste o hélice","texto":"O hélice fica na popa (a traseira da lancha) e pode ferir gravemente quem está na água. Por isso, guine para o bordo da queda, ou seja, vire a lancha para o mesmo lado em que a pessoa caiu. Assim, a popa e o hélice se afastam dela. Perto da pessoa, ponha o motor em neutro.","falaMarujo":"Caiu por boreste? Guine para boreste.","pose":"ensinando"},{"id":"q-hom-helice","tipo":"multipla-escolha","opcoes":["Para boreste, o bordo da queda, afastando o hélice dela","Para bombordo, afastando a lancha toda da pessoa","Para a frente, seguindo e voltando mais tarde","Para trás, dando ré imediatamente na direção dela"],"correta":0,"enunciado":"A pessoa caiu por boreste. Para onde você guina logo em seguida?","explicacao":"Guinando para o bordo da queda, a popa e o hélice se afastam da pessoa. Depois, quando chegar perto dela, ponha o motor em neutro.","referencia":"Salvatagem · Homem ao mar"},{"id":"c-hom-recolher","tipo":"conceito","titulo":"Chegando até a pessoa","texto":"Depois, volte e aproxime-se devagar por sotavento da pessoa, ou seja, vindo do lado para onde o vento sopra, com a proa apontada contra o vento (aproado ao vento). Assim, o vento não empurra a lancha para cima dela. Junto da pessoa, desligue o motor e recolha-a pelo bordo, a lateral da lancha. Nunca a recolha pela popa com o motor ligado.","falaMarujo":"Chegue devagar e desligue o motor ao lado dela."}]},{"id":"salvatagem-socorro","temaId":"salvatagem","titulo":"Pedindo socorro","descricao":"Rádio VHF, as chamadas MAYDAY, PAN-PAN e SECURITÉ e os sinais pirotécnicos","cartoes":[{"id":"c-socorro","pose":"ensinando","tipo":"conceito","texto":"Se você precisar de ajuda no mar, o rádio VHF é o meio principal. O canal 16 é o canal de socorro, urgência, segurança e chamada, e é escutado pela Marinha e pelas embarcações. Por telefone, o Salvamar atende no 185.","titulo":"Pedindo socorro","falaMarujo":"Canal 16 no rádio, 185 no telefone."},{"id":"q-vhf","tipo":"multipla-escolha","opcoes":["Canal 16","Canal 9","Canal 68","Canal 72"],"correta":0,"enunciado":"Em qual canal do rádio VHF marítimo você pede socorro?","explicacao":"O canal 16 é o canal de socorro, urgência, segurança e chamada, e é escutado pela Marinha e pelas embarcações.","referencia":"Comunicações · VHF marítimo"},{"id":"c-mayday-panpan","tipo":"conceito","titulo":"MAYDAY ou PAN-PAN","texto":"No rádio, a chamada começa com uma palavra-chave, dita três vezes, que mostra a gravidade. MAYDAY é para perigo grave e iminente à vida ou à embarcação. PAN-PAN é para urgência, quando ainda não há perigo imediato.","falaMarujo":"Vida em risco agora, MAYDAY. Só urgência, PAN-PAN.","pose":"pensando"},{"id":"c-securite","tipo":"conceito","titulo":"SECURITÉ","texto":"Há uma terceira palavra-chave, que não é pedido de ajuda. SECURITÉ serve para dar um aviso de segurança à navegação ou um aviso de tempo, para que todos que escutam o canal fiquem atentos.","falaMarujo":"SECURITÉ não pede ajuda: avisa."},{"id":"q-panpan","tipo":"multipla-escolha","opcoes":["PAN-PAN: urgência, sem perigo imediato","MAYDAY: perigo grave e iminente","Não chamar: esperar alguém passar","SECURITÉ: aviso de segurança à navegação"],"correta":0,"enunciado":"O motor pifou em mar calmo, longe das pedras, e você precisa de um reboque. Como chamar no rádio?","explicacao":"Como não há perigo imediato à vida, é uma urgência, então a chamada é PAN-PAN. MAYDAY fica para perigo grave e iminente, como naufrágio, incêndio fora de controle ou alguém correndo risco de vida.","referencia":"Comunicações · Socorro e urgência"},{"id":"c-pirotecnicos","tipo":"conceito","titulo":"Sinais pirotécnicos","texto":"Os sinais pirotécnicos fazem você ser visto quando pede socorro. De dia, use o fumígeno laranja, que solta uma fumaça laranja. À noite, o foguete com paraquedas, de luz vermelha, é visto de longe.","falaMarujo":"Dia pede fumaça laranja. Noite pede foguete vermelho."},{"id":"c-facho","tipo":"conceito","titulo":"Facho manual","texto":"Quando o socorro já está por perto, use o facho manual vermelho. Ele é segurado na mão e mostra sua posição a quem já está próximo de você.","falaMarujo":"Facho na mão: para quem já está perto."},{"id":"q-pirotecnico-dia","tipo":"multipla-escolha","opcoes":["Fumígeno laranja","Foguete com paraquedas vermelho","Facho manual vermelho","Apito de emergência"],"correta":0,"enunciado":"Em pleno dia, você vê um avião de busca ao longe. Qual sinal pirotécnico usar?","explicacao":"De dia, a fumaça laranja se destaca contra o mar e é vista de longe. Acenda o fumígeno a sotavento da embarcação, ou seja, do lado para onde o vento sopra. Foguete e facho vermelho funcionam melhor à noite.","referencia":"Salvatagem · Sinais pirotécnicos"},{"id":"c-dsc","tipo":"conceito","titulo":"O botão de socorro do rádio","texto":"Alguns rádios VHF têm DSC, a chamada seletiva digital. Eles têm um botão vermelho de socorro que manda sua identificação, o número chamado MMSI. Se o rádio estiver ligado ao GPS, ele manda também a sua posição.","falaMarujo":"Botão vermelho do DSC: ele pede socorro por você."}]},{"id":"salvatagem-prevencao","temaId":"salvatagem","titulo":"Prevenção e água fria","descricao":"Triângulo do fogo, abastecimento seguro, hipotermia e quando abandonar a lancha","cartoes":[{"id":"c-triangulo-fogo","pose":"ensinando","tipo":"conceito","texto":"Para existir, o fogo precisa de três coisas ao mesmo tempo: combustível, oxigênio e calor. Esse é o triângulo do fogo. Se você tirar qualquer um dos três, o fogo apaga.","titulo":"Triângulo do fogo","falaMarujo":"Tirou um lado do triângulo, o fogo cai."},{"id":"c-abastecer","tipo":"conceito","titulo":"Abastecendo com segurança","texto":"Na lancha a gasolina, uma das principais causas de incêndio e explosão é o vapor de combustível. Por isso, abasteça com o motor desligado, sem passageiros a bordo, sem ninguém fumando e com as escotilhas fechadas. Escotilhas são as aberturas com tampa no convés.","falaMarujo":"Abastecer: motor desligado, passageiros fora, cigarro apagado.","pose":"ensinando"},{"id":"c-ventilar","tipo":"conceito","titulo":"Ventile antes da partida","texto":"Depois de abastecer, ventile o compartimento do motor antes de dar a partida. O vapor de gasolina é mais pesado que o ar e se acumula no porão, e uma faísca na partida pode causar explosão.","falaMarujo":"Abasteceu? Ventile o porão antes de girar a chave.","pose":"bravo"},{"id":"q-triangulo","tipo":"multipla-escolha","opcoes":["Combustível, oxigênio e calor","Combustível, água e faísca","Calor, fumaça e oxigênio","Gasolina, óleo e eletricidade"],"correta":0,"enunciado":"Quais são os três elementos do triângulo do fogo?","explicacao":"Os três são combustível, oxigênio e calor, e sem um deles o fogo não existe. Por isso o extintor age abafando (tira o oxigênio), resfriando (tira o calor) ou isolando o combustível. Alguns livros falam em tetraedro, somando a reação em cadeia, que o pó químico interrompe.","referencia":"Combate a incêndio · Triângulo do fogo"},{"id":"q-abastecer","tipo":"multipla-escolha","opcoes":["Motor desligado, sem passageiros e com ventilação antes da partida","Motor ligado, para não perder tempo no posto","Passageiros a bordo, ajudando com a mangueira","Motor desligado, com partida logo após fechar o tanque"],"correta":0,"enunciado":"Hora de abastecer a lancha no posto. Qual é o procedimento certo?","explicacao":"O certo é desligar o motor, tirar os passageiros e ventilar antes da partida. O vapor de gasolina é mais pesado que o ar e se acumula no porão, e uma faísca na partida pode causar explosão.","referencia":"Segurança · Abastecimento"},{"id":"c-agua-fria","pose":"ensinando","tipo":"conceito","texto":"Na água, o corpo perde calor muito rápido, e isso pode levar à hipotermia, que é a queda perigosa da temperatura do corpo. Por isso, se você estiver de colete, não nade à toa: nadar gasta energia e faz você perder ainda mais calor.","titulo":"Na água, poupe calor","falaMarujo":"De colete na água fria, nadar à toa só esfria."},{"id":"c-posicao-help","tipo":"conceito","titulo":"A posição HELP","texto":"Para perder menos calor, fique encolhido, com os joelhos junto ao peito e os braços cruzados à frente. Essa é a posição HELP, sigla em inglês para a postura que reduz a perda de calor. Se houver mais gente na água, fiquem em grupo, abraçados. E mantenha a roupa no corpo, porque ela ajuda a segurar o calor.","falaMarujo":"Joelhos no peito e roupa no corpo."},{"id":"c-abandono","tipo":"conceito","titulo":"Fique com a embarcação","texto":"Só abandone a embarcação em último caso, porque ela é mais fácil de achar do que uma pessoa sozinha no mar. Se der, suba nela, mesmo que esteja virada: fora da água, você perde muito menos calor.","falaMarujo":"Barco boiando é sua melhor boia.","pose":"pensando"},{"id":"q-hipotermia","tipo":"multipla-escolha","opcoes":["Ficar encolhido, joelhos no peito, sem nadar à toa","Nadar sem parar, para se manter aquecido","Tirar a roupa, para nadar mais leve","Tirar o colete, para nadar melhor"],"correta":0,"enunciado":"Você caiu na água fria, de colete, e o resgate vai demorar. O que fazer?","explicacao":"Encolhido na posição HELP, ou abraçado ao grupo, você perde menos calor e aguenta mais tempo. Nadar gasta energia e aumenta a perda de calor.","referencia":"Sobrevivência · Hipotermia"},{"id":"q-abandono","tipo":"multipla-escolha","opcoes":["Só em último caso: a embarcação é mais fácil de achar","Imediatamente, antes mesmo de pedir socorro","Assim que entrar a primeira água a bordo","Quando a bateria do rádio acabar"],"correta":0,"enunciado":"A lancha está com água a bordo, mas ainda flutua. Quando abandonar?","explicacao":"Abandone a lancha só em último caso, porque a embarcação é mais fácil de achar do que uma pessoa. Enquanto ela flutuar, fique nela ou agarrado a ela: vista o colete, peça socorro e use os pirotécnicos. Abandone só se ela afundar ou se houver fogo fora de controle. Se ela virar e continuar flutuando, suba no casco.","referencia":"Sobrevivência · Abandono"}]}]}$conteudo$::jsonb);
